    <h1>Parent Component</h1>

    <div v-if="loading">Loading...</div>
    <div v-else-if="error">Error: {{ error }}</div>
    <div v-else>
      <!-- Pass the fetched data as a prop to the child -->
      <ChildComponent :user="userData" />
    </div>
  </div>
</template>
